//! Comptime manifest of the batch fixtures — ~1000 distinct cells of one
//! DGGS family at one resolution, with a pinned convergence count.
//! Generated by scripts/batches/gen_batches.py; the `.ids` beside each
//! `.zon` is the portable artifact it was emitted from.
//!
//! Plain `@import`, like the case fixtures: ten 430 KB files measured at
//! +0.25 s on a cold `zig build test` and +130 MB compiler peak RSS (dev.md
//! "Test layout" has the numbers and the size at which a runtime loader
//! becomes the right shape instead).

/// The pin is one-sided — `converged >= converged_at_least` — because
/// which cells clear the f64 gap floor is decided at FP-noise level and
/// differs between zig's two backends (CLAUDE.md). `converged_at_least ==
/// cells.len` is the exact case: every cell converges, which forces the
/// DNC / infeasible / errored tallies to zero. `errored == 0` holds for
/// every batch and is a test invariant, not part of the pin.
pub const Batch = struct {
    description: []const u8,
    converged_at_least: u32,
    cells: []const []const [3]f64,
};

pub const Entry = struct {
    name: []const u8,
    batch: Batch,
};

pub const all: []const Entry = &.{
    .{ .name = "h3_r9", .batch = @import("batches/h3_r9.zon") },
    .{ .name = "h3_r15", .batch = @import("batches/h3_r15.zon") },
    .{ .name = "s2_L15", .batch = @import("batches/s2_L15.zon") },
    .{ .name = "s2_L19", .batch = @import("batches/s2_L19.zon") },
    .{ .name = "s2_L23", .batch = @import("batches/s2_L23.zon") },
    .{ .name = "a5_r14", .batch = @import("batches/a5_r14.zon") },
    .{ .name = "a5_r18", .batch = @import("batches/a5_r18.zon") },
    .{ .name = "a5_r23", .batch = @import("batches/a5_r23.zon") },
};
